import sys; sys.path.insert(0,'.')
from lib import *
P,y,ids,X = load_data(practice, tokenize, LABELS)
V=30522
n = np.array([len(t) for t in ids]); Xtf = sp.diags(1.0/n)@X
res = {}
for seed in [0,1,2]:
    rng=np.random.RandomState(seed); perm=rng.permutation(len(P)); folds=np.array_split(perm,5)
    def nbS(tr,alpha):
        cnt=np.zeros((V,8))
        for c in range(8): cnt[:,c]=np.asarray(X[tr][y[tr]==c].sum(0)).ravel()
        lp=np.log(cnt+alpha)-np.log(cnt.sum(0)+alpha*V); return lp-lp.mean(1,keepdims=True)
    def ridgeS(tr,lam):
        Xc=Xtf[tr]; Yc=np.eye(8)[y[tr]]
        Kk=(Xc@Xc.T).toarray(); A=np.linalg.solve(Kk+lam*np.eye(len(tr)), Yc-Yc.mean(0))
        S=np.asarray(Xc.T@A); return S-S.mean(1,keepdims=True)
    for name,fn in [('nb0.1',lambda tr:nbS(tr,0.1)),('nb0.3',lambda tr:nbS(tr,0.3)),('nb0.5',lambda tr:nbS(tr,0.5)),
                    ('ridge1e-3',lambda tr:ridgeS(tr,1e-3)),('ridge3e-3',lambda tr:ridgeS(tr,3e-3)),('ridge1e-2',lambda tr:ridgeS(tr,1e-2)),
                    ('blend',lambda tr: nbS(tr,0.3)/4 + ridgeS(tr,3e-3)*1.0)]:
        pred=np.zeros(len(P),int)
        for f in folds:
            tr=np.setdiff1d(np.arange(len(P)),f); S=fn(tr)
            pred[f]=(X[f]@S).argmax(1)   # sum = n*mean; argmax same w/o bias
        res.setdefault(name,[]).append((pred==y).mean())
for k,v in res.items(): print(k, np.round(v,4), np.mean(v))
# magnitude of NB scores
S=np.load('S_nb.npy'); K=np.load('K.npy')
nr=np.linalg.norm(S[K],axis=1); print('||S|| pct', np.percentile(nr,[50,90,99,100]), 'max entry', np.abs(S[K]).max())
